using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        SeedData();
        _controller = new InstructorsController(_context);
    }

    private void SeedData()
    {
        var dept = new Department { DepartmentID = 1, Name = "Engineering", Budget = 200000, StartDate = new DateTime(2000, 1, 1) };
        _context.Departments.Add(dept);

        var course1 = new Course { CourseID = 101, Title = "Intro to CS", Credits = 3, DepartmentID = 1 };
        var course2 = new Course { CourseID = 102, Title = "Data Structures", Credits = 4, DepartmentID = 1 };
        _context.Courses.AddRange(course1, course2);

        var instructor = new Instructor
        {
            ID = 1,
            LastName = "Fakhouri",
            FirstMidName = "Fadi",
            HireDate = new DateTime(2002, 7, 6),
            OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Room 101" },
            CourseAssignments = new List<CourseAssignment>
            {
                new CourseAssignment { InstructorID = 1, CourseID = 101 }
            }
        };
        _context.Instructors.Add(instructor);

        var instructor2 = new Instructor
        {
            ID = 2,
            LastName = "Harui",
            FirstMidName = "Roger",
            HireDate = new DateTime(1998, 7, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor2);
        _context.SaveChanges();
    }

    [Fact]
    public void Index_NoParameters_ReturnsViewWithInstructors()
    {
        // Act
        var result = _controller.Index(null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        // Act
        var result = _controller.Index(1, null) as ViewResult;

        // Assert
        var model = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(result!.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
        Assert.Equal("Intro to CS", model.Courses.First().Title);
    }

    [Fact]
    public void Index_WithCourseId_PopulatesEnrollments()
    {
        // Arrange - add enrollment
        var student = new Student { ID = 10, LastName = "Test", FirstMidName = "Student", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        _context.Enrollments.Add(new Enrollment { EnrollmentID = 1, CourseID = 101, StudentID = 10, Grade = Grade.A });
        _context.SaveChanges();

        // Act
        var result = _controller.Index(1, 101) as ViewResult;

        // Assert
        var model = Assert.IsType<Models.SchoolViewModels.InstructorIndexData>(result!.Model);
        Assert.NotNull(model.Enrollments);
        Assert.Single(model.Enrollments);
    }

    [Fact]
    public void Details_ValidId_ReturnsInstructorView()
    {
        // Act
        var result = _controller.Details(1) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Fakhouri", instructor.LastName);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null) as StatusCodeResult;

        // Assert
        Assert.Equal(400, result!.StatusCode);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Details(999) as NotFoundResult;

        // Assert
        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithCourseData()
    {
        // Act
        var result = _controller.Create() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(instructor.CourseAssignments);
    }

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        // Arrange
        var instructor = new Instructor
        {
            LastName = "NewInstructor",
            FirstMidName = "Test",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
        var result = _controller.Create(instructor, null!) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(3, _context.Instructors.Count());
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AssignsCourses()
    {
        // Arrange
        var instructor = new Instructor
        {
            LastName = "CourseInstructor",
            FirstMidName = "Test",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        var selectedCourses = new[] { "101", "102" };

        // Act
        var result = _controller.Create(instructor, selectedCourses) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var saved = _context.Instructors.First(i => i.LastName == "CourseInstructor");
        var assignments = _context.CourseAssignments.Where(ca => ca.InstructorID == saved.ID).ToList();
        Assert.Equal(2, assignments.Count);
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsView()
    {
        // Arrange
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            FirstMidName = "NoLastName",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
        var result = _controller.Create(instructor, null!) as ViewResult;

        // Assert
        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsInstructorView()
    {
        // Act
        var result = _controller.Edit(1) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Fakhouri", instructor.LastName);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Edit((int?)null) as StatusCodeResult;

        // Assert
        Assert.Equal(400, result!.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsInstructorView()
    {
        // Act
        var result = _controller.Delete(1) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Fakhouri", instructor.LastName);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Delete(null) as StatusCodeResult;

        // Assert
        Assert.Equal(400, result!.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Delete(999) as NotFoundResult;

        // Assert
        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_RemovesInstructorAndClearsDepartmentAdmin()
    {
        // Arrange - set instructor as department admin
        var dept = _context.Departments.First();
        dept.InstructorID = 1;
        _context.SaveChanges();

        // Act
        var result = _controller.DeleteConfirmed(1) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Single(_context.Instructors);
        var updatedDept = _context.Departments.Find(dept.DepartmentID);
        Assert.Null(updatedDept!.InstructorID);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }
}

